-- ============================================================
-- Mục #3: Chất lượng dữ liệu purchase
-- Quyết định: quy tắc dedup, định nghĩa "người mua"
-- ============================================================

-- 3a. Coverage các trường quan trọng của purchase
SELECT
  COUNT(*) AS n_purchase_events,
  COUNTIF(ecommerce.transaction_id IS NOT NULL) AS with_transaction_id,
  COUNTIF(ecommerce.purchase_revenue_in_usd IS NOT NULL) AS with_revenue_usd,
  COUNTIF(ecommerce.total_item_quantity IS NOT NULL) AS with_total_quantity,
  COUNTIF(ARRAY_LENGTH(items) = 0) AS purchase_with_zero_items,
  COUNT(DISTINCT ecommerce.transaction_id) AS n_distinct_transaction_id,
  ROUND(SUM(ecommerce.purchase_revenue_in_usd), 2) AS total_revenue_usd
FROM `bigquery-public-data.ga4_obfuscated_sample_ecommerce.events_*`
WHERE event_name = 'purchase'
  AND _TABLE_SUFFIX BETWEEN '20201101' AND '20210131';

-- 3b. Danh sách transaction_id bị lặp (>1 dòng purchase cho cùng user + transaction)
-- Bôi đen câu này rồi Run selection
SELECT
  user_pseudo_id,
  ecommerce.transaction_id,
  COUNT(*) AS n_rows,
  COUNT(DISTINCT event_timestamp) AS n_distinct_timestamps,
  COUNT(DISTINCT event_date) AS n_distinct_dates,
  ROUND(SUM(ecommerce.purchase_revenue_in_usd), 2) AS sum_revenue,
  MIN(FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%S', TIMESTAMP_MICROS(event_timestamp))) AS first_seen,
  MAX(FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%S', TIMESTAMP_MICROS(event_timestamp))) AS last_seen
FROM `bigquery-public-data.ga4_obfuscated_sample_ecommerce.events_*`
WHERE event_name = 'purchase'
  AND ecommerce.transaction_id IS NOT NULL
  AND _TABLE_SUFFIX BETWEEN '20201101' AND '20210131'
GROUP BY user_pseudo_id, ecommerce.transaction_id
HAVING COUNT(*) > 1
ORDER BY n_rows DESC
LIMIT 50;


